<script setup lang="ts">
import {ref,onMounted,watch} from 'vue'
import {api} from './api'
import {type Plan,money,parseMoney} from './billing'
const props=defineProps<{userId?:string,admin?:boolean,plans:Plan[]}>()
const emit=defineEmits<{changed:[],error:[string]}>()
const state=ref<any>(null),invoices=ref<any[]>([]),busy=ref(false),version=ref(''),confirmed=ref(false),payment=ref<any>(null),amount=ref(''),reference=ref('')
async function load(){const q=props.userId?'?user_id='+encodeURIComponent(props.userId):'';state.value=(await api('billing/status'+q)).subscription;invoices.value=await api('billing/invoices'+q)}
async function run(f:()=>Promise<void>){busy.value=true;try{await f()}catch(e){emit('error',e instanceof Error?e.message:String(e))}finally{busy.value=false}}
async function subscribe(){await run(async()=>{await api('billing/subscriptions','POST',{user_id:props.userId||'',plan_version:version.value,confirmed:confirmed.value});confirmed.value=false;await load();emit('changed')})}
async function settle(){await run(async()=>{await api('billing/settle','POST',{user_id:props.userId||'',confirmed:true});await load();emit('changed')})}
function prepare(i:any){payment.value=i;amount.value=(i.remaining_minor/100).toFixed(2);reference.value='';confirmed.value=false}
async function pay(){await run(async()=>{await api('billing/payments','POST',{invoice_id:payment.value.id,amount_minor:parseMoney(amount.value),reference:reference.value,confirmed:confirmed.value});payment.value=null;confirmed.value=false;await load();emit('changed')})}
watch(()=>props.userId,()=>run(load));onMounted(()=>run(load))
</script>
<template><section class="paper"><div class="section-heading"><h2>Abonament lunar și sold</h2><Button label="Reverifică soldul" text @click="run(load)" :loading="busy"/></div>
<template v-if="state"><Message :severity="state.suspended?'error':state.outstanding_minor>0?'warn':'success'">{{state.suspended?'Accesul de lucru este suspendat.':'Abonamentul este activ.'}} {{state.reason==='subscription_payment_overdue'?'Există sume restante după termenul de cinci zile.':state.reason==='credit_limit_exhausted'?'Limita de credit este epuizată.':'Sumele neachitate trebuie achitate în cinci zile de la emitere.'}}</Message><div class="stats"><article class="stat"><span>Rest emis</span><strong>{{money(state.outstanding_minor,state.currency)}}</strong></article><article class="stat"><span>Consum neemis</span><strong>{{money(state.unbilled_usage_minor,state.currency)}}</strong></article><article class="stat"><span>Credit utilizat / limită</span><strong>{{money(state.credit_used_minor,state.currency)}} / {{money(state.credit_limit_minor,state.currency)}}</strong></article><article class="stat"><span>Credit rezervat / incert</span><strong>{{money(state.reserved_credit_minor,state.currency)}}</strong></article></div><p>Următoarea reînnoire: {{new Date(state.period_end).toLocaleString('ro-RO')}}.</p><p class="muted small">Achitarea sumelor restante și eliberarea creditului reactivează automat accesul. Plata numai a abonamentului nu stinge separat datoria pentru consum AI.</p><Button v-if="state.unbilled_usage_minor>0" label="Pregătește soldul de consum pentru plată" @click="settle" :loading="busy"/></template>
<form v-else @submit.prevent="subscribe"><p>Fără abonament lunar. Pachetul administrativ existent își păstrează limitele.</p><label>Pachet lunar<Select v-model="version" :options="plans.filter(p=>p.active&&p.code!=='free')" optionLabel="name" optionValue="version_id" placeholder="Alege pachetul"/></label><p v-if="version">{{money(plans.find(p=>p.version_id===version)!.monthly_price_minor,plans.find(p=>p.version_id===version)!.currency)}} / lună</p><label class="check"><input type="checkbox" v-model="confirmed"/> Confirm prețul, prima lună integrală fără proratare și reînnoirea în prima zi a fiecărei luni UTC. Termen de plată: cinci zile.</label><Button label="Activează abonamentul lunar" type="submit" :disabled="!confirmed||!version||busy"/></form>
<div v-if="invoices.length" class="table-wrap"><table><thead><tr><th>Document</th><th>Total</th><th>Rest de plată</th><th>Scadență</th><th v-if="admin"></th></tr></thead><tbody><tr v-for="i in invoices" :key="i.id"><td>{{i.kind==='usage'?'Consum AI':i.kind==='template_addon'?'Șablon suplimentar':'Abonament'}}<br/><small v-if="i.template_name">{{i.template_name}} · {{new Date(i.period_start).toLocaleDateString('ro-RO',{month:'long',year:'numeric',timeZone:'UTC'})}}<br/></small><small>{{i.reference}}</small></td><td>{{money(i.amount_minor,i.currency)}}</td><td>{{money(i.remaining_minor,i.currency)}}</td><td>{{new Date(i.due_at).toLocaleString('ro-RO')}}</td><td v-if="admin"><Button v-if="i.remaining_minor>0" label="Înregistrează plata verificată" @click="prepare(i)"/></td></tr></tbody></table></div>
<form v-if="payment&&admin" @submit.prevent="pay"><h3>Plată verificată · {{payment.reference}}</h3><label>Sumă în {{payment.currency}}<InputText v-model="amount" inputmode="decimal" required/></label><label>Referința unică a plății efectiv primite<InputText v-model="reference" required minlength="3" maxlength="200"/></label><label class="check"><input type="checkbox" v-model="confirmed"/> Confirm că plata a fost primită și verificată.</label><Button label="Confirmă înregistrarea plății" type="submit" :disabled="!confirmed||busy"/></form><p class="muted small">Documentele sunt evidențe interne ale soldului, nu facturi fiscale/e-Factura. Plata online EuPlătesc urmează; pentru achitare transmite administratorului referința documentului.</p></section></template>
